import importlib.util
import json
from pathlib import Path
import subprocess
import sys

import pytest
import yaml

ROOT = Path(__file__).resolve().parent.parent
TREES = [ROOT / 'scratch' / 'baseline', ROOT / 'project']


def load(tree, filename):
    spec = importlib.util.spec_from_file_location('fixture_' + tree.name + filename, tree / filename)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


@pytest.mark.parametrize('value', [None, False, 0, '', 'text', [], {}, object()])
def test_identity_unchanged(value):
    for tree in TREES:
        assert load(tree, 'cast_target.py').read_value(value) is value


@pytest.mark.parametrize('text', ['', 'null', '0', 'false', 'value: 2', '[1, 2, 10]',
                                 'same: 1\nsame: 2', '[', '---\na\n---\nb',
                                 '!!python/object/apply:os.system ["echo unsafe"]'])
def test_yaml_differential(text):
    results = []
    for tree in TREES:
        try:
            results.append(('value', load(tree, 'yaml_target.py').read_document(text)))
        except yaml.YAMLError as error:
            results.append(('error', type(error).__name__, str(error)))
    assert results[0] == results[1]
    if text.startswith('!!python'):
        assert results[0][0] == 'error'


@pytest.mark.parametrize('tree', TREES)
@pytest.mark.parametrize('text', ['answer: 42', '['])
def test_disposal_on_success_and_failure(tree, text, monkeypatch):
    disposals = []
    original = yaml.SafeLoader

    class TrackingLoader(original):
        def dispose(self):
            disposals.append(True)
            super().dispose()

    monkeypatch.setattr(yaml, 'SafeLoader', TrackingLoader)
    reader = load(tree, 'yaml_target.py').read_document
    if text == '[':
        with pytest.raises(yaml.YAMLError):
            reader(text)
    else:
        assert reader(text) == {'answer': 42}
    assert disposals == [True]


@pytest.mark.parametrize('preloaded', [False, True])
def test_runtime_backend_selection_and_path_unchanged(preloaded):
    code = '''import json, pathlib, sys, types
root = pathlib.Path(sys.argv[1])
sys.path.insert(0, str(root))
if sys.argv[2] == "yes":
    module = types.ModuleType("report_backend")
    module.render = lambda: "preloaded"
    sys.modules["report_backend"] = module
import import_target
print(json.dumps({"result": import_target.render_report(), "path": sys.path[0] == str(root / "vendor"), "top_level": "report_backend" in sys.modules}))
'''
    outputs = []
    for tree in TREES:
        result = subprocess.run([sys.executable, '-c', code, str(tree), 'yes' if preloaded else 'no'],
                                capture_output=True, text=True, check=True)
        outputs.append(json.loads(result.stdout))
    assert outputs[0] == outputs[1]
    assert outputs[1] == {'result': 'preloaded' if preloaded else 'ok', 'path': True, 'top_level': True}
